type UserTeamsRow struct {
	ID          string             `json:"id"`
	Name        string             `json:"name"`
	Timezone    string             `json:"timezone"`
	CreatedAt   pgtype.Timestamptz `json:"created_at"`
	Role        string             `json:"role"`
	DisplayName string             `json:"display_name"`
}

func (q *Queries) UserTeams(ctx context.Context, userID string) ([]UserTeamsRow, error) {
	rows, err := q.db.Query(ctx, userTeams, userID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []UserTeamsRow
	for rows.Next() {
		var i UserTeamsRow
		if err := rows.Scan(
			&i.ID,
			&i.Name,
			&i.Timezone,
			&i.CreatedAt,
			&i.Role,
			&i.DisplayName,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
